-- ===========================================================================
-- GO_LIVE.sql — everything the live database needs, in one run.
--
-- GENERATED by scripts/build-go-live.sh from:
--   supabase/migrations/0010_service_sequence.sql
--   supabase/migrations/0011_brand_framework.sql
--   supabase/seed_sterling.sql
-- Do not hand-edit. Change a source file and run the script again.
--
-- WHERE: Supabase dashboard -> SQL Editor -> New query -> paste -> Run.
--
-- SAFE TO RE-RUN. Every column is added with `if not exists`, every insert
-- updates on conflict instead of duplicating. Running it twice changes nothing
-- the second time, so a half-finished run is fixed by running it again.
--
-- It does NOT touch visits, answers, evidence or anything a shopper records.
-- It installs the questionnaire and the three outlets, nothing else.
--
-- WHAT IT DOES NOT DO: create the people who sign in. Supabase Auth owns
-- passwords, so each shopper must be added under Authentication -> Users
-- first, and then supabase/create_shoppers.sql links them to shopper records.
--
-- The last thing it prints is a check. questions must read 603.
-- ===========================================================================

-- Stop early with a clear message rather than a wall of errors if the base
-- schema was never installed.
do $$
begin
  if to_regclass('public.audit_questions') is null then
    raise exception 'Base schema missing. Run migrations 0001-0009 first, then this file.';
  end if;
end $$;


-- ===========================================================================
-- PART 1 of 3 — migration 0010: the service-sequence engine
-- ===========================================================================
-- 0010 — Service sequence engine: stage-weighted templates, KPI mapping, conditional
-- questions and per-visit stage / KPI scores.
--
-- Every column added here is nullable, and nothing else changes: a template without
-- stage weights scores exactly as before, so existing rows need no backfill and no
-- policy is touched (RLS is row-level; these are columns on tables it already covers).
--
-- Apply BEFORE deploying an app build that carries sequence templates. The app
-- persists whole rows, so a save of a stage template or a visit on one against a
-- database without these columns fails with "column does not exist".

-- Which service sequence template a brand is assessed against (audit_templates.code).
alter table public.brands
  add column if not exists template_code text;

-- Industry / service model / visit mode, main KPIs, critical failures, timing chain.
alter table public.audit_templates
  add column if not exists sequence jsonb;

-- A section is a stage of the sequence: its share of the visit score and its KPI name.
alter table public.audit_sections
  add column if not exists stage_weight numeric(5,2)
    check (stage_weight is null or (stage_weight >= 0 and stage_weight <= 100)),
  add column if not exists kpi_name text;

-- Question → main KPI mapping, timing-chain leg, and the sibling answer that gates it.
alter table public.audit_questions
  add column if not exists kpi_keys text[],
  add column if not exists timing_role text
    check (timing_role is null or timing_role in ('queue','order','preparation')),
  add column if not exists condition jsonb;

-- Stored beside category_scores so reports need no recomputation.
alter table public.visits
  add column if not exists stage_scores jsonb,
  add column if not exists kpi_scores jsonb;

-- Counter-service visits are a journey of their own.
-- The inline checks in 0001 were auto-named <table>_<column>_check.
alter table public.audit_templates drop constraint if exists audit_templates_journey_check;
alter table public.audit_templates add constraint audit_templates_journey_check check (journey in (
  'In-store / Dine-in','Social Media Interaction','Takeaway','Delivery',
  'Entertainment Ticketing','Reception','Guest Onboarding','Safety Briefing','Digital Interaction',
  'Counter Order'));

alter table public.visits drop constraint if exists visits_journey_check;
alter table public.visits add constraint visits_journey_check check (journey in (
  'In-store / Dine-in','Social Media Interaction','Takeaway','Delivery',
  'Entertainment Ticketing','Reception','Guest Onboarding','Safety Briefing','Digital Interaction',
  'Counter Order'));


-- ===========================================================================
-- PART 2 of 3 — migration 0011: brand frameworks
-- ===========================================================================
-- 0011 — Brand frameworks: calculated durations, clock stamps and conditional comments.
--
-- Added for SHEBESTAN_FINE_DINING, where the shopper records wall-clock times and the
-- questionnaire works the elapsed minutes out for itself, and where the client's rule
-- is that every No and every Average or Poor rating must be explained.
--
-- Like 0010, every column here is nullable and nothing else changes: a question with
-- none of them behaves exactly as it does today. Apply BEFORE deploying an app build
-- that carries a template using them — the app persists whole rows, so a save against
-- a database without these columns fails with "column does not exist".
--
-- Depends on: 0010_service_sequence.sql.

-- A `time` question whose minutes are calculated rather than typed:
--   {"from": "PRF.1", "to": "HOS.1"} — the codes of two `clock` questions.
alter table public.audit_questions
  add column if not exists derived_from jsonb;

-- Require a comment when the answer falls short (a No, a Fail, a bottom-half rating),
-- as distinct from comment_required, which asks for one whatever the answer.
alter table public.audit_questions
  add column if not exists comment_on_fail boolean not null default false;

-- `clock` joins the question types: a wall-clock stamp (HH:MM), never scored.
do $$
begin
  if exists (
    select 1 from pg_constraint
    where conname = 'audit_questions_type_check' and conrelid = 'public.audit_questions'::regclass
  ) then
    alter table public.audit_questions drop constraint audit_questions_type_check;
  end if;
  alter table public.audit_questions
    add constraint audit_questions_type_check
    check (type in ('yes_no', 'rating_5', 'rating_10', 'pass_fail', 'multiple_choice', 'text', 'numeric', 'time', 'clock', 'photo', 'video'));
end $$;

-- How full the outlet was when the shopper arrived, as a percentage of seats or
-- service points in use. Context for every timing on the visit.
alter table public.visits
  add column if not exists occupancy integer check (occupancy is null or (occupancy between 0 and 100));

-- A stage weight may now carry a decimal (14.2), so a client's own weighting can be
-- scaled to 100 without rounding it into something they would not recognise.
-- numeric(5,2) already allows this; the comment records why it matters.
comment on column public.audit_sections.stage_weight is
  'Percent of the visit score carried by this stage. One decimal place is meaningful: a client weighting that sums to something other than 100 is scaled, not rounded. A stage whose every scored question is gated is conditional and sits outside the 100.';


