-- ===========================================================================
-- CHECK — read every row. Anything marked FAIL means the run did not finish.
-- ===========================================================================
select
  label,
  actual,
  expected,
  case when actual = expected then 'OK' else 'FAIL' end as result
from (
  values
    ('brands',    (select count(*) from public.brands),          3::bigint),
    ('outlets',   (select count(*) from public.outlets),         3::bigint),
    ('templates', (select count(*) from public.audit_templates), 3::bigint),
    ('stages',    (select count(*) from public.audit_sections),  53::bigint),
    ('questions', (select count(*) from public.audit_questions), 603::bigint)
) as t(label, actual, expected);
